        "details": "بلغ النبي ﷺ أن الروم وحلفاءهم جمعوا جموعاً ضخمة على حدود الشام للإغارة على المدينة. وكانت الظروف بالغة القسوة؛ حر لاهب، وجدب في الثمار، وبُعد شاق للطريق، فسميت «غزوة العسرة». ضرب الصحابة أروع أمثلة التضحية بالمال؛ فجاء أبو بكر بكل ماله، وجاء عمر بنصف ماله، وجهز عثمان بن عفان ثلث الجيش (جهّز 300 بعير بأقتابها وأحلاسها وألف دينار صبها في حجر النبي)، فقال النبي متأثراً: «ما ضر عثمان ما عمل بعد اليوم». وسار جيش المسلمين (30 ألف مقاتل) في استعراض مهيب لقوة الدولة الإسلامية حتى بلغوا تبوك. ولما سمع الروم بقدوم هذا الجيش الجرار قذف الله في قلوبهم الرعب وتفرقوا في داخل بلادهم دون قتال، وعقد النبي معاهدات صلح مع أمراء القبائل الحدودية. وفضحت سورة التوبة المنافقين الذين اعتذروا وتخلفوا، وجرى ابتلاء عظيم لثلاثة من خيرة الصحابة (كعب بن مالك، مرارة بن الربيع، هلال بن أمية) الذين صدقوا ولم ينافقوا فظلوا 50 ليلة حتى ضاقت عليهم الأرض بما رحبت، فأنزل الله توبته عليهم في القرآن.",
