        "details": "بدأ وجع النبي ﷺ أواخر صفر بعد عودته من مقبرة البقيع وشهداء أحد، واشتدت عليه الحمى فاستأذن زوجاته أن يُمَرَّض في بيت عائشة رضي الله عنها. ولما عجز عن الخروج أمر أن يصلي أبو بكر بالناس. وقبل وفاته بيسير كشف ستر الحجرة ونظر إلى الصحابة وهم صفوف في صلاة الفجر فتبسم فرحاً باجتماعهم على الدين، فكان ذلك آخر عهدهم به. وفي ضحى يوم الاثنين 12 ربيع الأول استاك بسواك عبد الرحمن بن أبي بكر بعد أن لينته عائشة بريقها، ثم شخص بصره نحو سقف الحجرة ورفع أصبعه وقال: «مع الذين أنعمت عليهم من النبيين والصديقين والشهداء والصالحين، اللهم اغفر لي وارحمني وألحقني بالرفيق الأعلى... اللهم الرفيق الأعلى!». وفاضت روحه الطاهرة وهو مسند رأسه إلى صدر عائشة رضي الله عنها. دهش الصحابة وصعقوا لهول الفاجعة، فوقف عمر بن الخطاب شاهر السيف من هول الصدمة ينكر موته، حتى أقبل أبو بكر الصديق برباطة جأش وثبات ويقين، فقبل جبين النبي الشريف وبكى وقال: «طبت حياً وميتاً يا رسول الله»، ثم خرج إلى الناس فخطب خطبته التاريخية: «ألا من كان يعبد محمداً فإن محمداً قد مات، ومن كان يعبد الله فإن الله حي لا يموت»، وتلا قوله تعالى: ﴿وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ﴾، فكأن الناس لم يعلموا أن الآية نزلت إلا يومئذٍ، واستقرت القلوب وأجمعوا على خلافة الصديق وحفظ الأمانة.",
